mozilla::Result<nsCString, nsresult> DatabaseUtils::Normalize(
    const nsACString& inString) {
  nsAutoCString outString;
  auto rv = nfc_normalize(inString, outString);
  if (NS_FAILED(rv)) {
    return mozilla::Err(rv);
  }
  return outString;
}

NS_IMPL_ISUPPORTS(TagsMatchFunction, mozIStorageFunction)

NS_IMETHODIMP TagsMatchFunction::OnFunctionCall(
    mozIStorageValueArray* aArguments, nsIVariant** aResult) {
  MOZ_ASSERT(aArguments);
  MOZ_ASSERT(aResult);

  uint32_t argc;
  aArguments->GetNumEntries(&argc);

  if (argc != 2) {
    NS_WARNING("Don't call me with the wrong number of arguments!");
    return NS_ERROR_INVALID_ARG;
  }

  int32_t type;
  bool found = false;
  aArguments->GetTypeOfIndex(0, &type);
  if (type != mozIStorageStatement::VALUE_TYPE_NULL) {
    if (type != mozIStorageStatement::VALUE_TYPE_TEXT) {
      NS_WARNING("Don't call me with the wrong type of argument 1!");
      return NS_ERROR_UNEXPECTED;
    }
    aArguments->GetTypeOfIndex(1, &type);
    if (type != mozIStorageStatement::VALUE_TYPE_TEXT) {
      NS_WARNING("Don't call me with the wrong type of argument 2!");
      return NS_ERROR_UNEXPECTED;
    }

    nsAutoCString haystack;
    aArguments->GetUTF8String(0, haystack);
    size_t haystackLength = haystack.Length();
    size_t h = 0;

    nsAutoCString needle;
    aArguments->GetUTF8String(1, needle);
    size_t needleLength = needle.Length();
    size_t n = 0;

    bool matchingStart = true;
    for (; h < haystackLength; ++h) {
      char c = haystack[h];
      if (c == ' ') {
        // At the end of a token.
        if (n == needleLength) {
          // Found the needle. Stop.
          found = true;
          break;
        }
        // Reset.
        matchingStart = true;
        n = 0;
      } else if (matchingStart && n < needleLength && c == needle[n]) {
        // In a token and it matches the needle so far.
        n++;
      } else {
        // In a token and it doesn't match the needle.
        matchingStart = false;
      }
    }
    if (h == haystackLength && n == needleLength) {
      found = true;
    }
  }

  nsCOMPtr<nsIVariant> result =
      new mozilla::storage::BooleanVariant(found == mWanted);
  result.forget(aResult);
  return NS_OK;
}

